#include <bits/stdc++.h>
using namespace std;

#define ll long long
ll dp[50010];
ll solve(int n, int P, int Q, vector<pair<int, int>>& weapons) {
    dp[0] = 0;

    for (auto& weapon : weapons) {
        int p = weapon.first;
        int c = weapon.second;
        for (int j = Q; j >= c; --j) {
            if (dp[j - c]>=0) {
                dp[j] = max(dp[j], dp[j - c] + p);
            }
        }
    }
    for (int j = 0; j <= Q; ++j) {
        if (dp[j] >= P) {
            return j;
        }
    }

    return -1;
}

int main() {
    int t;
    cin>>t;
    while(t--){
        int n, P, Q;
        cin >> n >> P >> Q;
        memset(dp,-0x3f,sizeof dp);
        vector<pair<int, int> > weapons(n);
        for (int i = 0; i < n; ++i) {
            cin >> weapons[i].first >> weapons[i].second;
        }
        cout << solve(n, P, Q, weapons) << "\n";
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int N = 1e5+10;
int a[N];
int sum[N];
int down[N];
vector<int> g[N];
void dfs_down(int x,int fa){
    down[x]=1;
    for(int i:g[x]){
        if(i!=fa){
            dfs_down(i,x);
            if(a[x]>a[i]){
                down[x]+=down[i];
            }
        }
    }
}
void dfs_sum(int x,int fa){
    if(a[x]>a[fa]){
        sum[x]+=sum[fa]+down[fa];
    }
    for(int i:g[x]){
        if(i!=fa){
            dfs_sum(i,x);
        }
    }
}
int main(){
    int n;
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    for(int i=1;i<n;i++){
        int u,v;
        cin>>u>>v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    dfs_down(1,0);
    dfs_sum(1,0);
    int mx = 0;
    for(int i=1;i<=n;i++){
        mx = max(mx,sum[i]+down[i]);
    }
    cout<<mx<<"\n";

}
